        // Actual vertical specific thrust (sum / m)
        const specThrust = kT * uf + dyBias / Math.max(0.5, dirY);

        // Horizontal disturbance observer
        const aKnownX = specThrust * dirX - (0.42 / massEst) * vxHat;
        const aKnownZ = specThrust * dirZ - (0.42 / massEst) * vzHat;
        const vPredX = vxHat + (aKnownX + dxHat) * dt;
        const vPredZ = vzHat + (aKnownZ + dzHat) * dt;
        const evX = v.x - vPredX;
        const evZ = v.z - vPredZ;
        const fastX = Math.abs(evX) > 0.024;
        const fastZ = Math.abs(evZ) > 0.024;
        vxHat = vPredX + (fastX ? 0.85 : 0.55) * evX;
        vzHat = vPredZ + (fastZ ? 0.85 : 0.55) * evZ;
        dxHat = clamp(dxHat + (fastX ? 48.0 : 20.0) * evX, -15.0, 15.0);
        dzHat = clamp(dzHat + (fastZ ? 48.0 : 20.0) * evZ, -15.0, 15.0);
      } else {
        vxHat = v.x; vyHat = v.y; vzHat = v.z;
      }

      if (p.y > 0.08) {
        rollTrim = clamp(rollTrim + 0.8 * (lastRollDes - att.roll) * dt, -0.25, 0.25);
        pitchTrim = clamp(pitchTrim + 0.8 * (lastPitchDes - att.pitch) * dt, -0.25, 0.25);
      }

      let tx, ty, tz;
      let kpX = 5.5, kdX = 4.0;
      let kpZ = 6.5, kdZ = 4.5;
      let kpY = 7.0, kdY = 4.2;
      let maxVelX = 1.7, maxVelZ = 1.7, maxVelY = 1.6;

      if (obs.gateIndex < 3) {
        const gate = obs.nextGate.centre;
        if (currentGate !== obs.gateIndex) {
          currentGate = obs.gateIndex;
          phase = 'align';
          settleCount = 0;
          ix = 0; iz = 0;
        }
        const gx = gate.x, gy = gate.y, gz = gate.z;

        if (phase === 'align') {
          tx = gx - 0.32;
          ty = gy;
          tz = gz;
          kpZ = 10.0; kdZ = 5.5;
          const errZ = Math.abs(p.z - gz);
          const errY = Math.abs(p.y - gy);
          const errX = Math.abs(p.x - tx);
          if (errZ < 0.020 && Math.abs(v.z) < 0.10 && errY < 0.07 && Math.abs(v.y) < 0.25 && errX < 0.16 && p.x < gx - 0.06) {
