            phase = 'cross';
          }
        }
        if (phase === 'cross') {
          tx = gx + 0.28;
          ty = gy;
          tz = gz;
          kpZ = 14.0; kdZ = 6.5;
          kpY = 8.5; kdY = 4.8;
