            const yPred = p.y + v.y * tCross;
            if (Math.abs(p.z - gz) > 0.024 || Math.abs(zPred - gz) > 0.026 || Math.abs(p.y - gy) > 0.10 || Math.abs(yPred - gy) > 0.11) {
              phase = 'align';
              settleCount = 0;
              tx = gx - 0.28;
            }
          }
        }
        if (prevGateCenter && p.x < prevGateCenter.x + 0.12 && Math.abs(p.x - prevGateCenter.x) < 0.16) {
          tz = prevGateCenter.z;
          ty = prevGateCenter.y;
        } else if (phase === 'cross') {
          prevGateCenter = { x: gx, y: gy, z: gz };
        }
      } else {
        const pad = obs.pad.centre;
        if (phase !== 'descend') {
          phase = 'pad_align';
        }
