        tz = pad.z;
        if (prevGateCenter && p.x < prevGateCenter.x + 0.12) {
          tz = prevGateCenter.z;
        }
        const distXZ = Math.hypot(p.x - pad.x, p.z - pad.z);
        const speedXZ = Math.hypot(v.x, v.z);
        if (phase === 'pad_align') {
          ty = 0.40;
          if (distXZ < 0.25) ty = 0.18;
          if (distXZ < 0.12 && speedXZ < 0.28 && p.y < 0.30) {
            phase = 'descend';
          }
        }
        if (phase === 'descend') {
          ty = 0.04;
          kpX = 7.5; kdX = 4.8;
          kpZ = 7.5; kdZ = 4.8;
          if (distXZ > 0.135) {
            ty = 0.15;
          }
        }
      }

      if (Math.abs(tx - p.x) < 0.25) ix = clamp(ix + (tx - p.x) * dt, -0.3, 0.3);
      else ix *= 0.95;
      if (Math.abs(tz - p.z) < 0.25) iz = clamp(iz + (tz - p.z) * dt, -0.3, 0.3);
      else iz *= 0.95;

      const desVx = clamp((kpX / kdX) * (tx - p.x) + 0.5 * ix, -maxVelX, maxVelX);
      const desVz = clamp((kpZ / kdZ) * (tz - p.z) + 0.8 * iz, -maxVelZ, maxVelZ);
      const desVy = clamp((kpY / kdY) * (ty - p.y), -maxVelY, maxVelY);

      const axCmd = kdX * (desVx - v.x);
      const azCmd = kdZ * (desVz - v.z);
      const ayCmd = kdY * (desVy - v.y);

      const dragCoeff = 0.42 / massEst;
      const reqTx = clamp(axCmd - dxHat + dragCoeff * v.x, -6.8, 6.8);
      const reqTz = clamp(azCmd - dzHat + dragCoeff * v.z, -6.8, 6.8);
      const reqTy = clamp(ayCmd + 9.81 - dyBias + dragCoeff * v.y, 2.5, 18.0);

      const tBodyX = cy * reqTx - sy * reqTz;
      const tBodyZ = sy * reqTx + cy * reqTz;

      const pitchDes = Math.atan2(tBodyX, reqTy);
      const rollDes = -Math.atan2(tBodyZ, Math.hypot(reqTy, tBodyX));

      const maxTilt = (obs.gateIndex === 3 && p.y < 0.13) ? 0.15 : 0.58;
      const roll = clamp(rollDes + 0.3 * (rollDes - att.roll) - 0.025 * rates.roll + rollTrim, -maxTilt, maxTilt);
      const pitch = clamp(pitchDes + 0.3 * (pitchDes - att.pitch) - 0.025 * rates.pitch + pitchTrim, -maxTilt, maxTilt);

      let thrust = reqTy / (kT * Math.max(0.5, dirY));
      if (obs.gateIndex === 3 && phase === 'descend' && p.y <= 0.09 && Math.hypot(p.x - obs.pad.centre.x, p.z - obs.pad.centre.z) <= 0.13 && Math.hypot(v.x, v.y, v.z) < 0.40) {
        thrust = Math.min(thrust, (9.81 * 0.25) / kT);
      }
      thrust = clamp(thrust, 0.02, 1.0);

      const yawRate = clamp(-1.5 * att.yaw, -0.8, 0.8);

      lastRollDes = rollDes;
      lastPitchDes = pitchDes;
      lastThrustCmd = thrust;
      stepCount++;

      return { thrust, roll, pitch, yawRate };
    }
  };
}

