export default function makeController() {
  const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));
  let stepCount = 0;
  let kT = 20.0;
  let massEst = 0.78;
  let uf = 0;
  let vyStart = null, yStart = null, tStart = null, thrustIntegral = 0;

  let vxHat = 0, vzHat = 0;
  let dxHat = 0, dzHat = 0;
  let ix = 0, iz = 0, iy = 0;

  let lastThrustCmd = 0.5;

  let currentGate = 0;
  let phase = 'align';
  let settleCount = 0;
  let prevGateCenter = null;

  return {
    step(obs) {
      const dt = 0.01;
      const p = obs.pos, v = obs.vel, att = obs.att, rates = obs.rates;

      const alphaMotor = 1 - Math.exp(-dt / 0.04);
      uf += (lastThrustCmd - uf) * alphaMotor;

      const bodyX = Math.sin(att.pitch) * Math.cos(att.roll);
      const bodyZ = -Math.sin(att.roll);
      const cy = Math.cos(att.yaw), sy = Math.sin(att.yaw);
      const dirX = cy * bodyX + sy * bodyZ;
      const dirY = Math.cos(att.pitch) * Math.cos(att.roll);
      const dirZ = -sy * bodyX + cy * bodyZ;

      if (p.y > 0.085 && stepCount > 3) {
        if (tStart === null) {
          tStart = obs.t;
          vyStart = v.y;
          yStart = p.y;
          thrustIntegral = 0;
        } else {
          thrustIntegral += uf * dirY * dt;
          if (thrustIntegral > 0.08) {
            const dragY = (0.42 / massEst) * (p.y - yStart);
            const lhs = (v.y - vyStart) + 9.81 * (obs.t - tStart) + dragY;
            const newKT = clamp(lhs / thrustIntegral, 14.5, 27.5);
            kT = 0.8 * kT + 0.2 * newKT;
            massEst = clamp(15.0 / kT, 0.60, 0.95);
          }
        }
      }

      if (stepCount === 0) {
        vxHat = v.x;
        vzHat = v.z;
      } else if (p.y > 0.075) {
        const aKnownX = kT * uf * dirX - (0.42 / massEst) * vxHat;
        const aKnownZ = kT * uf * dirZ - (0.42 / massEst) * vzHat;
        const vPredX = vxHat + (aKnownX + dxHat) * dt;
        const vPredZ = vzHat + (aKnownZ + dzHat) * dt;
        const evX = v.x - vPredX;
        const evZ = v.z - vPredZ;
        const fastX = Math.abs(evX) > 0.025;
        const fastZ = Math.abs(evZ) > 0.025;
        vxHat = vPredX + (fastX ? 0.85 : 0.55) * evX;
        vzHat = vPredZ + (fastZ ? 0.85 : 0.55) * evZ;
        dxHat = clamp(dxHat + (fastX ? 45.0 : 18.0) * evX, -15.0, 15.0);
        dzHat = clamp(dzHat + (fastZ ? 45.0 : 18.0) * evZ, -15.0, 15.0);
      } else {
        vxHat = v.x;
        vzHat = v.z;
      }

      let tx, ty, tz;
      let kpX = 5.5, kdX = 3.8;
      let kpZ = 6.5, kdZ = 4.2;
      let kpY = 6.5, kdY = 4.0;
      let maxVelX = 1.8, maxVelZ = 1.8, maxVelY = 1.6;

      if (obs.gateIndex < 3) {
        const gate = obs.nextGate.centre;
        if (currentGate !== obs.gateIndex) {
          currentGate = obs.gateIndex;
          phase = 'align';
          settleCount = 0;
          ix = 0; iz = 0;
        }
        const gx = gate.x, gy = gate.y, gz = gate.z;

        if (phase === 'align') {
          tx = gx - 0.32;
          ty = gy;
          tz = gz;
          kpZ = 9.5; kdZ = 5.2;
          const errZ = Math.abs(p.z - gz);
          const errY = Math.abs(p.y - gy);
          const errX = Math.abs(p.x - tx);
          if (errZ < 0.019 && Math.abs(v.z) < 0.09 && errY < 0.065 && Math.abs(v.y) < 0.22 && errX < 0.16 && p.x < gx - 0.06) {
            settleCount++;
          } else {
            settleCount = Math.max(0, settleCount - 1);
          }
          if (settleCount >= 5) {
            phase = 'cross';
          }
        }
        if (phase === 'cross') {
          tx = gx + 0.28;
          ty = gy;
          tz = gz;
          kpZ = 13.5; kdZ = 6.2;
          kpY = 8.0; kdY = 4.5;
          maxVelX = 1.25;
          const distToPlane = gx - p.x;
          if (distToPlane > 0 && distToPlane < 0.26) {
            const tCross = clamp(distToPlane / Math.max(0.15, v.x), 0.02, 0.32);
            const zPred = p.z + v.z * tCross;
            const yPred = p.y + v.y * tCross;
            if (Math.abs(p.z - gz) > 0.023 || Math.abs(zPred - gz) > 0.025 || Math.abs(p.y - gy) > 0.10 || Math.abs(yPred - gy) > 0.11) {
              phase = 'align';
              settleCount = 0;
              tx = gx - 0.28;
            }
          }
        }
        if (prevGateCenter && p.x < prevGateCenter.x + 0.12 && Math.abs(p.x - prevGateCenter.x) < 0.16) {
          tz = prevGateCenter.z;
          ty = prevGateCenter.y;
        } else if (phase === 'cross') {
          prevGateCenter = { x: gx, y: gy, z: gz };
        }
      } else {
        const pad = obs.pad.centre;
        if (phase !== 'descend') {
          phase = 'pad_align';
        }
        tx = pad.x;
        tz = pad.z;
        if (prevGateCenter && p.x < prevGateCenter.x + 0.12) {
          tz = prevGateCenter.z;
        }
        const distXZ = Math.hypot(p.x - pad.x, p.z - pad.z);
        const speedXZ = Math.hypot(v.x, v.z);
        if (phase === 'pad_align') {
          ty = 0.35;
          if (distXZ < 0.30) ty = 0.16;
          if (distXZ < 0.12 && speedXZ < 0.30 && p.y < 0.28) {
            phase = 'descend';
          }
        }
        if (phase === 'descend') {
          ty = 0.03;
          kpX = 7.5; kdX = 4.8;
          kpZ = 7.5; kdZ = 4.8;
          if (distXZ > 0.135) {
            ty = 0.14;
          }
        }
      }

      if (Math.abs(tx - p.x) < 0.22) ix = clamp(ix + (tx - p.x) * dt, -0.25, 0.25);
      else ix *= 0.9;
      if (Math.abs(tz - p.z) < 0.22) iz = clamp(iz + (tz - p.z) * dt, -0.25, 0.25);
      else iz *= 0.9;
      if (Math.abs(ty - p.y) < 0.30) iy = clamp(iy + (ty - p.y) * dt, -0.4, 0.4);
      else iy *= 0.95;

      const desVx = clamp((kpX / kdX) * (tx - p.x) + 0.6 * ix, -maxVelX, maxVelX);
      const desVz = clamp((kpZ / kdZ) * (tz - p.z) + 0.9 * iz, -maxVelZ, maxVelZ);
      const desVy = clamp((kpY / kdY) * (ty - p.y) + 0.8 * iy, -maxVelY, maxVelY);

      const axCmd = kdX * (desVx - v.x);
      const azCmd = kdZ * (desVz - v.z);
      const ayCmd = kdY * (desVy - v.y);

      const dragCoeff = 0.42 / massEst;
      const reqTx = clamp(axCmd - dxHat + dragCoeff * v.x, -6.5, 6.5);
      const reqTz = clamp(azCmd - dzHat + dragCoeff * v.z, -6.5, 6.5);
      const reqTy = clamp(ayCmd + 9.81 + dragCoeff * v.y, 2.5, 18.0);

      const tBodyX = cy * reqTx - sy * reqTz;
      const tBodyZ = sy * reqTx + cy * reqTz;

      const pitchDes = Math.atan2(tBodyX, reqTy);
      const rollDes = -Math.atan2(tBodyZ, Math.hypot(reqTy, tBodyX));

      const maxTilt = (obs.gateIndex === 3 && p.y < 0.13) ? 0.15 : 0.58;
      const roll = clamp(rollDes, -maxTilt, maxTilt);
      const pitch = clamp(pitchDes, -maxTilt, maxTilt);

      let thrust = reqTy / (kT * Math.max(0.5, dirY));
      if (obs.gateIndex === 3 && phase === 'descend' && p.y <= 0.095 && Math.hypot(p.x - obs.pad.centre.x, p.z - obs.pad.centre.z) <= 0.135 && Math.hypot(v.x, v.y, v.z) < 0.42) {
        thrust = Math.min(thrust, (9.81 * 0.2) / kT);
      }
      thrust = clamp(thrust, 0.02, 1.0);

      const yawRate = clamp(-1.5 * att.yaw, -0.8, 0.8);

      lastThrustCmd = thrust;
      stepCount++;

      return { thrust, roll, pitch, yawRate };
    }
  };
}

export default function makeController() {
  const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));
  let stepCount = 0;
  let kT = 20.0;
  let massEst = 0.78;
  let uf = 0;

  let tCal = null, vyCal = 0, yCal = 0, vxCal = 0, xCal = 0, vzCal = 0, zCal = 0;
  let intThrX = 0, intThrY = 0, intThrZ = 0;

  let baseDx = 0, baseDz = 0;
  let gustDx = 0, gustDz = 0;
  let vxHat = 0, vyHat = 0, vzHat = 0;

  let ix = 0, iy = 0, iz = 0;
  let lastThrustCmd = 0.5;
  let currentGate = 0;
  let prevGate = null;
  let descendMode = false;

  return {
    step(obs) {
      const dt = 0.01;
      const p = obs.pos, v = obs.vel, att = obs.att, rates = obs.rates;

      const alphaMotor = 1 - Math.exp(-dt / 0.038);
      uf += (lastThrustCmd - uf) * alphaMotor;

      const bodyX = Math.sin(att.pitch) * Math.cos(att.roll);
      const bodyZ = -Math.sin(att.roll);
      const cy = Math.cos(att.yaw), sy = Math.sin(att.yaw);
      const dirX = cy * bodyX + sy * bodyZ;
      const dirY = Math.cos(att.pitch) * Math.cos(att.roll);
      const dirZ = -sy * bodyX + cy * bodyZ;

      if (stepCount === 0) {
        vxHat = v.x; vyHat = v.y; vzHat = v.z;
      }

      // Calibration during gust-free window (0.10s <= t <= 1.98s)
      if (p.y > 0.085 && obs.t >= 0.08 && obs.t <= 1.98) {
        if (tCal === null) {
          tCal = obs.t;
          vyCal = v.y; yCal = p.y;
          vxCal = v.x; xCal = p.x;
          vzCal = v.z; zCal = p.z;
          intThrX = 0; intThrY = 0; intThrZ = 0;
        } else {
          const dtCal = obs.t - tCal;
          intThrY += uf * dirY * dt;
          intThrX += uf * dirX * dt;
          intThrZ += uf * dirZ * dt;
          if (intThrY > 0.06 && dtCal > 0.08) {
            const dragCoeff = 0.42 / massEst;
            const totalAy = (v.y - vyCal) + 9.81 * dtCal + dragCoeff * (p.y - yCal);
            const newKT = clamp(totalAy / intThrY, 14.5, 27.5);
            kT = 0.7 * kT + 0.3 * newKT;
            massEst = clamp(15.1 / kT, 0.60, 0.95);
          }
          if (dtCal > 0.18) {
            const dragCoeff = 0.42 / massEst;
            const estBaseX = ((v.x - vxCal) + dragCoeff * (p.x - xCal) - kT * intThrX) / dtCal;
            const estBaseZ = ((v.z - vzCal) + dragCoeff * (p.z - zCal) - kT * intThrZ) / dtCal;
            baseDx = clamp(0.6 * baseDx + 0.4 * estBaseX, -2.5, 2.5);
            baseDz = clamp(0.6 * baseDz + 0.4 * estBaseZ, -2.5, 2.5);
          }
        }
      }

      // Real-time velocity + gust disturbance observer
      if (p.y > 0.08 && stepCount > 0) {
        const dragCoeff = 0.42 / massEst;
        const aKnownY = kT * uf * dirY - 9.81 - dragCoeff * vyHat;
        const vPredY = vyHat + aKnownY * dt;
        const evY = v.y - vPredY;
        vyHat = vPredY + 0.55 * evY;
        if (obs.t > 1.98 && uf * dirY > 0.25) {
          kT = clamp(kT + 1.2 * evY / (uf * dirY), 14.5, 27.5);
          massEst = clamp(15.1 / kT, 0.60, 0.95);
        }

        const totalDx = baseDx + gustDx;
        const totalDz = baseDz + gustDz;
        const aKnownX = kT * uf * dirX - dragCoeff * vxHat;
        const aKnownZ = kT * uf * dirZ - dragCoeff * vzHat;
        const vPredX = vxHat + (aKnownX + totalDx) * dt;
        const vPredZ = vzHat + (aKnownZ + totalDz) * dt;
        const evX = v.x - vPredX;
        const evZ = v.z - vPredZ;

        if (obs.t < 1.98) {
          vxHat = vPredX + 0.6 * evX;
          vzHat = vPredZ + 0.6 * evZ;
          gustDx = 0;
          gustDz = 0;
        } else {
          const jumpX = Math.abs(evX) > 0.024;
          const jumpZ = Math.abs(evZ) > 0.024;
          vxHat = vPredX + (jumpX ? 0.85 : 0.55) * evX;
          vzHat = vPredZ + (jumpZ ? 0.85 : 0.55) * evZ;
          gustDx = clamp(gustDx + (jumpX ? 50.0 : 22.0) * evX, -12.0, 12.0);
          gustDz = clamp(gustDz + (jumpZ ? 50.0 : 22.0) * evZ, -12.0, 12.0);
          if (Math.abs(gustDx) < 0.15 && !jumpX) gustDx *= 0.92;
          if (Math.abs(gustDz) < 0.15 && !jumpZ) gustDz *= 0.92;
        }
      } else {
        vxHat = v.x; vyHat = v.y; vzHat = v.z;
      }

      const dxHat = baseDx + gustDx;
      const dzHat = baseDz + gustDz;

      // Trajectory & Gate Corridor Planner
      let tx, ty, tz;
      let kpX = 6.0, kdX = 4.2;
      let kpZ = 9.0, kdZ = 5.0;
      let kpY = 7.5, kdY = 4.4;
      let maxVelX = 1.9, maxVelZ = 1.9, maxVelY = 1.7;

      if (obs.gateIndex < 3) {
        const gate = obs.nextGate.centre;
        if (currentGate !== obs.gateIndex) {
          const gates = [
            { x: -1.15, y: 1.05, z: -0.85 },
            { x: 0.15, y: 1.40, z: 0.25 },
            { x: 1.35, y: 1.05, z: 1.05 }
          ];
          prevGate = gates[currentGate];
          currentGate = obs.gateIndex;
          ix = 0; iz = 0;
        }
        const gx = gate.x, gy = gate.y, gz = gate.z;
        ty = gy;
        tz = gz;

        // Post-gate clearance lock: do not shift Y/Z until safely past previous gate X plane
        if (prevGate && p.x < prevGate.x + 0.16) {
