          currentGate = 3;
          ix = 0; iz = 0; iy = 0;
        }
        if (p.x < prevGate.x + 0.16) {
          tz = prevGate.z;
          ty = prevGate.y;
          tx = pad.x;
        } else {
          const distXZ = Math.hypot(p.x - pad.x, p.z - pad.z);
          const speedXZ = Math.hypot(v.x, v.z);
