            if (distXZ < 0.11 && speedXZ < 0.28 && p.y < 0.24) {
              descendMode = true;
            }
          }
          if (descendMode) {
            ty = 0.03;
            kpX = 8.5; kdX = 5.2;
            kpZ = 8.5; kdZ = 5.2;
            if (distXZ > 0.135) {
              ty = 0.14;
              descendMode = false;
            }
          }
        }
      }

      if (Math.abs(tx - p.x) < 0.20) ix = clamp(ix + (tx - p.x) * dt, -0.25, 0.25);
      else ix *= 0.90;
      if (Math.abs(tz - p.z) < 0.20) iz = clamp(iz + (tz - p.z) * dt, -0.25, 0.25);
      else iz *= 0.90;
      if (Math.abs(ty - p.y) < 0.25) iy = clamp(iy + (ty - p.y) * dt, -0.35, 0.35);
      else iy *= 0.92;

      const desVx = clamp((kpX / kdX) * (tx - p.x) + 0.8 * ix, -maxVelX, maxVelX);
      const desVz = clamp((kpZ / kdZ) * (tz - p.z) + 1.2 * iz, -maxVelZ, maxVelZ);
      const desVy = clamp((kpY / kdY) * (ty - p.y) + 0.9 * iy, -maxVelY, maxVelY);

      const axCmd = kdX * (desVx - v.x);
      const azCmd = kdZ * (desVz - v.z);
      const ayCmd = kdY * (desVy - v.y);

      const dragCoeff = 0.42 / massEst;
      const reqTx = clamp(axCmd - dxHat + dragCoeff * v.x, -6.8, 6.8);
      const reqTz = clamp(azCmd - dzHat + dragCoeff * v.z, -6.8, 6.8);
      const reqTy = clamp(ayCmd + 9.81 + dragCoeff * v.y, 2.2, 18.0);

      const tBodyX = cy * reqTx - sy * reqTz;
      const tBodyZ = sy * reqTx + cy * reqTz;

      const pitchDes = Math.atan2(tBodyX, reqTy);
      const rollDes = -Math.atan2(tBodyZ, Math.hypot(reqTy, tBodyX));

      const maxTilt = (obs.gateIndex === 3 && p.y < 0.13) ? 0.15 : 0.58;
      const roll = clamp(rollDes + 0.22 * (rollDes - att.roll) - 0.02 * rates.roll, -maxTilt, maxTilt);
      const pitch = clamp(pitchDes + 0.22 * (pitchDes - att.pitch) - 0.02 * rates.pitch, -maxTilt, maxTilt);

      let thrust = reqTy / (kT * Math.max(0.5, dirY));
      if (obs.gateIndex === 3 && descendMode && p.y <= 0.092 && Math.hypot(p.x - obs.pad.centre.x, p.z - obs.pad.centre.z) <= 0.135 && Math.hypot(v.x, v.y, v.z) < 0.40) {
        thrust = Math.min(thrust, (9.81 * 0.20) / kT);
      }
      thrust = clamp(thrust, 0.02, 1.0);

      const yawRate = clamp(-1.5 * att.yaw, -0.8, 0.8);

      lastThrustCmd = thrust;
      stepCount++;

      return { thrust, roll, pitch, yawRate };
    }
  };
}

