export default function makeController() {
  const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));
  let stepCount = 0;
  let kT = 20.0;
  let massEst = 0.78;
  let uf = 0.45;

  let tCal = null, vyCal = 0, yCal = 0;
  let intThrY = 0;

  let baseDx = 0, baseDz = 0;
  let gustDx = 0, gustDz = 0;
  let vxHat = 0, vyHat = 0, vzHat = 0;

  let ix = 0, iy = 0, iz = 0;
  let lastThrustCmd = 0.45;
  let currentGate = 0;
  let prevGate = null;
  let crossingGate = false;
  let descendMode = false;

  return {
    step(obs) {
      const dt = 0.01;
      const p = obs.pos, v = obs.vel, att = obs.att, rates = obs.rates;

      const alphaMotor = 1 - Math.exp(-dt / 0.04);
      uf += (lastThrustCmd - uf) * alphaMotor;

      const bodyX = Math.sin(att.pitch) * Math.cos(att.roll);
      const bodyZ = -Math.sin(att.roll);
      const cy = Math.cos(att.yaw), sy = Math.sin(att.yaw);
      const dirX = cy * bodyX + sy * bodyZ;
      const dirY = Math.cos(att.pitch) * Math.cos(att.roll);
      const dirZ = -sy * bodyX + cy * bodyZ;

      if (stepCount === 0) {
        vxHat = v.x; vyHat = v.y; vzHat = v.z;
      }

      // Calibrate kT and mass during initial climb (0.08s <= t <= 1.95s)
      if (p.y > 0.085 && obs.t >= 0.08 && obs.t <= 1.95) {
        if (tCal === null) {
          tCal = obs.t;
          vyCal = v.y; yCal = p.y;
          intThrY = 0;
        } else {
          const dtCal = obs.t - tCal;
          intThrY += uf * dirY * dt;
          if (intThrY > 0.06 && dtCal > 0.08) {
            const dragCoeff = 0.42 / massEst;
            const totalAy = (v.y - vyCal) + 9.81 * dtCal + dragCoeff * (p.y - yCal);
            const newKT = clamp(totalAy / intThrY, 14.5, 27.5);
            kT = 0.75 * kT + 0.25 * newKT;
            massEst = clamp(15.1 / kT, 0.60, 0.95);
          }
        }
      }

      const dragCoeff = 0.42 / massEst;

      // Real-time velocity + wind disturbance observer
      if (p.y > 0.08 && stepCount > 2) {
        const aThrustX = kT * uf * dirX;
        const aThrustZ = kT * uf * dirZ;
        const aKnownX = aThrustX - dragCoeff * vxHat;
        const aKnownZ = aThrustZ - dragCoeff * vzHat;

        const totalDx = baseDx + gustDx;
        const totalDz = baseDz + gustDz;
        const vPredX = vxHat + (aKnownX + totalDx) * dt;
        const vPredZ = vzHat + (aKnownZ + totalDz) * dt;
        const evX = v.x - vPredX;
        const evZ = v.z - vPredZ;

        if (obs.t < 1.98) {
          // Gust-free window: learn baseWind smoothly
          vxHat = vPredX + 0.55 * evX;
          vzHat = vPredZ + 0.55 * evZ;
          baseDx = clamp(baseDx + 14.0 * evX, -2.0, 2.0);
          baseDz = clamp(baseDz + 14.0 * evZ, -2.0, 2.0);
          gustDx = 0;
          gustDz = 0;
        } else {
          // Gust window: baseDx/baseDz locked, track gusts in gustDx/gustDz
          const jumpX = Math.abs(evX) > 0.025;
          const jumpZ = Math.abs(evZ) > 0.025;
          vxHat = vPredX + (jumpX ? 0.80 : 0.50) * evX;
          vzHat = vPredZ + (jumpZ ? 0.80 : 0.50) * evZ;
          gustDx = clamp(gustDx + (jumpX ? 38.0 : 16.0) * evX, -10.0, 10.0);
          gustDz = clamp(gustDz + (jumpZ ? 38.0 : 16.0) * evZ, -10.0, 10.0);
        }
      } else {
        vxHat = v.x; vyHat = v.y; vzHat = v.z;
      }

      const dxHat = baseDx + gustDx;
      const dzHat = baseDz + gustDz;

      // Current estimated net horizontal accelerations
      const aNetX = kT * uf * dirX - dragCoeff * v.x + dxHat;
      const aNetZ = kT * uf * dirZ - dragCoeff * v.z + dzHat;

      let tx, ty, tz;
      let kpX = 4.6, kdX = 3.6;
      let kpZ = 5.4, kdZ = 4.0;
      let kpY = 6.0, kdY = 3.8;
      let maxVelX = 1.4, maxVelZ = 1.4, maxVelY = 1.4;

      if (obs.gateIndex < 3) {
        const gate = obs.nextGate.centre;
        if (currentGate !== obs.gateIndex) {
          const gates = [
            { x: -1.15, y: 1.05, z: -0.85 },
            { x: 0.15, y: 1.40, z: 0.25 },
            { x: 1.35, y: 1.05, z: 1.05 }
          ];
          prevGate = gates[currentGate];
          currentGate = obs.gateIndex;
          crossingGate = false;
          ix = 0; iz = 0;
        }
        const gx = gate.x, gy = gate.y, gz = gate.z;
        ty = gy;
        tz = gz;

        if (prevGate && p.x < prevGate.x + 0.16) {
          // Clear previous gate plane before moving Y/Z
          ty = prevGate.y;
          tz = prevGate.z;
          tx = prevGate.x + 0.35;
          kpZ = 7.0; kdZ = 4.5;
        } else {
          const distX = gx - p.x;
          const errZ = Math.abs(p.z - gz);
          const errY = Math.abs(p.y - gy);
          const tCross = clamp(distX / Math.max(0.20, v.x), 0.03, 0.35);
          const zPred = p.z + v.z * tCross + 0.25 * aNetZ * tCross * tCross;
          const yPred = p.y + v.y * tCross;

          if (!crossingGate) {
            // Enter crossing mode when aligned in Y and Z
            if (distX > 0.04 && distX < 0.48 && errZ < 0.018 && Math.abs(zPred - gz) < 0.020 && Math.abs(v.z) < 0.09 && errY < 0.065 && Math.abs(v.y) < 0.22) {
              crossingGate = true;
            }
          } else {
            // Abort crossing if knocked out of safe Z/Y corridor before reaching gate plane
            if (distX > 0.03 && (errZ > 0.024 || Math.abs(zPred - gz) > 0.026 || errY > 0.10 || Math.abs(yPred - gy) > 0.11)) {
              crossingGate = false;
            }
          }

          if (crossingGate) {
            tx = gx + 0.32;
            kpZ = 7.5; kdZ = 4.8;
            kpY = 7.0; kdY = 4.2;
            maxVelX = 1.05;
          } else {
            tx = gx - 0.28;
            kpZ = 6.2; kdZ = 4.3;
          }
        }
      } else {
        const pad = obs.pad.centre;
        tx = pad.x;
        tz = pad.z;
        if (currentGate !== 3) {
          prevGate = { x: 1.35, y: 1.05, z: 1.05 };
          currentGate = 3;
          ix = 0; iz = 0; iy = 0;
        }
        if (prevGate && p.x < prevGate.x + 0.16) {
          tz = prevGate.z;
          ty = prevGate.y;
          tx = pad.x;
        } else {
          const distXZ = Math.hypot(p.x - pad.x, p.z - pad.z);
          const speedXZ = Math.hypot(v.x, v.z);
          kpX = 5.5; kdX = 4.2;
          kpZ = 5.5; kdZ = 4.2;
          if (!descendMode) {
            ty = distXZ > 0.30 ? 0.40 : 0.16;
            if (distXZ < 0.11 && speedXZ < 0.25 && p.y < 0.24) {
              descendMode = true;
            }
          }
          if (descendMode) {
            ty = 0.03;
            kpX = 6.2; kdX = 4.5;
            kpZ = 6.2; kdZ = 4.5;
            if (distXZ > 0.135) {
              ty = 0.14;
              descendMode = false;
            }
          }
        }
      }

      if (Math.abs(tx - p.x) < 0.22) ix = clamp(ix + (tx - p.x) * dt, -0.25, 0.25);
      else ix *= 0.92;
      if (Math.abs(tz - p.z) < 0.22) iz = clamp(iz + (tz - p.z) * dt, -0.25, 0.25);
      else iz *= 0.92;
      if (Math.abs(ty - p.y) < 0.25) iy = clamp(iy + (ty - p.y) * dt, -0.35, 0.35);
      else iy *= 0.92;

      const desVx = clamp((kpX / kdX) * (tx - p.x) + 0.7 * ix, -maxVelX, maxVelX);
      const desVz = clamp((kpZ / kdZ) * (tz - p.z) + 0.9 * iz, -maxVelZ, maxVelZ);
      const desVy = clamp((kpY / kdY) * (ty - p.y) + 0.8 * iy, -maxVelY, maxVelY);

      // Include acceleration damping (-0.14 * aNet) to compensate inner attitude/motor lag
      const axCmd = kdX * (desVx - v.x) - 0.14 * aNetX;
      const azCmd = kdZ * (desVz - v.z) - 0.14 * aNetZ;
      const ayCmd = kdY * (desVy - v.y);

      const reqTx = clamp(axCmd - dxHat + dragCoeff * v.x, -5.8, 5.8);
      const reqTz = clamp(azCmd - dzHat + dragCoeff * v.z, -5.8, 5.8);
      const reqTy = clamp(ayCmd + 9.81 + dragCoeff * v.y, 3.0, 14.5);

      const tBodyX = cy * reqTx - sy * reqTz;
      const tBodyZ = sy * reqTx + cy * reqTz;

      const pitchDes = Math.atan2(tBodyX, reqTy);
      const rollDes = -Math.atan2(tBodyZ, Math.hypot(reqTy, tBodyX));

      const maxTilt = (obs.gateIndex === 3 && p.y < 0.13) ? 0.15 : 0.52;
      const roll = clamp(rollDes + 0.20 * (rollDes - att.roll) - 0.02 * rates.roll, -maxTilt, maxTilt);
      const pitch = clamp(pitchDes + 0.20 * (pitchDes - att.pitch) - 0.02 * rates.pitch, -maxTilt, maxTilt);

      // Cap thrust at 0.78 during flight so motors never saturate at 4.0N and lose attitude control
      let thrust = reqTy / (kT * Math.max(0.55, dirY));
      if (obs.gateIndex === 3 && descendMode && p.y <= 0.092 && Math.hypot(p.x - obs.pad.centre.x, p.z - obs.pad.centre.z) <= 0.135 && Math.hypot(v.x, v.y, v.z) < 0.40) {
        thrust = Math.min(thrust, (9.81 * 0.20) / kT);
      }
      thrust = clamp(thrust, 0.02, 0.78);

      const yawRate = clamp(-1.2 * att.yaw, -0.6, 0.6);

      lastThrustCmd = thrust;
      stepCount++;

      return { thrust, roll, pitch, yawRate };
    }
  };
}

