            kpZ = 6.8; kdZ = 4.5;
            if (distXZ > 0.138) {
              ty = 0.13;
              descendMode = false;
            }
          }
        }
      }

      // Anti-windup integral: only integrate when close to target and low velocity
      if (Math.abs(tx - p.x) < 0.08 && Math.abs(v.x) < 0.18) {
        ix = clamp(ix + 2.2 * (tx - p.x) * dt, -0.22, 0.22);
      } else if (Math.abs(tx - p.x) > 0.18 || (tx - p.x) * ix < 0) {
        ix *= 0.85;
      }

      if (Math.abs(tz - p.z) < 0.06 && Math.abs(v.z) < 0.15) {
        iz = clamp(iz + 2.8 * (tz - p.z) * dt, -0.22, 0.22);
      } else if (Math.abs(tz - p.z) > 0.14 || (tz - p.z) * iz < 0) {
        iz *= 0.85;
      }

      if (Math.abs(ty - p.y) < 0.15 && Math.abs(v.y) < 0.25) {
        iy = clamp(iy + 1.8 * (ty - p.y) * dt, -0.35, 0.35);
      } else if (Math.abs(ty - p.y) > 0.25) {
        iy *= 0.90;
      }

      const desVx = clamp((kpX / kdX) * (tx - p.x) + ix, -maxVelX, maxVelX);
      const desVz = clamp((kpZ / kdZ) * (tz - p.z) + iz, -maxVelZ, maxVelZ);
      const desVy = clamp((kpY / kdY) * (ty - p.y) + iy, -maxVelY, maxVelY);

      const axCmd = kdX * (desVx - v.x) - 0.14 * aNetX;
      const azCmd = kdZ * (desVz - v.z) - 0.14 * aNetZ;
      const ayCmd = kdY * (desVy - v.y);

      const reqTx = clamp(axCmd - dxHat + dragCoeff * v.x, -5.8, 5.8);
      const reqTz = clamp(azCmd - dzHat + dragCoeff * v.z, -5.8, 5.8);
      const reqTy = clamp(ayCmd + 9.81 + dragCoeff * v.y, 2.8, 14.5);

      const tBodyX = cy * reqTx - sy * reqTz;
      const tBodyZ = sy * reqTx + cy * reqTz;

      const pitchDes = Math.atan2(tBodyX, reqTy);
      const rollDes = -Math.atan2(tBodyZ, Math.hypot(reqTy, tBodyX));

      const maxTilt = (obs.gateIndex === 3 && p.y < 0.13) ? 0.15 : 0.52;
      const roll = clamp(rollDes + 0.20 * (rollDes - att.roll) - 0.02 * rates.roll, -maxTilt, maxTilt);
      const pitch = clamp(pitchDes + 0.20 * (pitchDes - att.pitch) - 0.02 * rates.pitch, -maxTilt, maxTilt);

      let thrust = reqTy / (kT * Math.max(0.55, dirY));
      if (obs.gateIndex === 3 && descendMode && p.y <= 0.092 && Math.hypot(p.x - obs.pad.centre.x, p.z - obs.pad.centre.z) <= 0.135 && Math.hypot(v.x, v.y, v.z) < 0.42) {
        thrust = Math.min(thrust, (9.81 * 0.18) / kT);
      }
      thrust = clamp(thrust, 0.02, 0.78);

      const yawRate = clamp(-1.2 * att.yaw, -0.6, 0.6);

      lastThrustCmd = thrust;
      stepCount++;

      return { thrust, roll, pitch, yawRate };
    }
  };
}

