import("./tasks/drone-hard/task.mjs").then(async ({ trialParameters, random }) => {
  const { initialState } = await import("./tasks/drone-hard/sim.mjs");
  const makeController = (await import("./controller.js")).default;
  for (const seed of [101, 102]) {
    const p = trialParameters(seed);
    const s = initialState(p);
    const ctrl = makeController();
    const rng = random((seed ^ 0xa5a5a5a5) >>> 0);
    // run 200 steps (2.0s)
    let lastAct;
    for (let step = 0; step < 200; step++) {
      const noise = (n) => (rng() + rng() + rng() - 1.5) * n;
      const vec = (v, n) => Object.fromEntries(Object.entries(v).map(([k, val]) => [k, val + noise(n)]));
      const obs = {
        t: +s.t.toFixed(4), pos: vec(s.pos, 0.001), vel: vec(s.vel, 0.018),
        att: vec(s.att, 0.003), rates: vec(s.rates, 0.012),
        gateIndex: s.gateIndex, nextGate: { centre: { x: -1.15, y: 1.05, z: -0.85 }, normal: { x: 1, y: 0, z: 0 } },
        pad: { centre: { x: 2.05, y: 0, z: 1.65 } }
      };
      lastAct = ctrl.step(obs);
      // integrate 2 substeps
      for (let sub = 0; sub < 2; sub++) {
        const dt = 0.005;
        const inertia = 0.006 * p.mass / 0.6;
        const torque = {};
        for (const axis of ["roll", "pitch"]) {
          const error = lastAct[axis] - s.att[axis];
          s.integral[axis] = Math.max(-0.35, Math.min(0.35, s.integral[axis] + error * dt));
          torque[axis] = inertia * (65 * error - 13 * s.rates[axis] + 22 * s.integral[axis]);
        }
        torque.yaw = inertia * 8 * (lastAct.yawRate - s.rates.yaw);
        const MX = [-1, 1, 1, -1], MZ = [-1, -1, 1, 1], SP = [1, -1, 1, -1];
        for (let i = 0; i < 4; i++) {
          const des = lastAct.thrust * 4 + torque.roll * MZ[i] / 0.46 - torque.pitch * MX[i] / 0.46 + torque.yaw * SP[i] / 0.056;
          const tgt = Math.max(0, Math.min(4, des)) * (i === p.weakMotor ? 1 - p.weakness : 1);
          s.motors[i] += (tgt - s.motors[i]) * (1 - Math.exp(-dt / p.lag));
        }
        const sum = s.motors.reduce((a, b) => a + b, 0);
        const mom = (sg) => s.motors.reduce((a, f, i) => a + f * sg[i], 0);
        s.rates.roll += (0.115 * mom(MZ) / inertia - 0.4 * s.rates.roll) * dt;
        s.rates.pitch += (-0.115 * mom(MX) / inertia - 0.4 * s.rates.pitch) * dt;
        s.rates.yaw += (0.014 * mom(SP) / inertia - 0.4 * s.rates.yaw) * dt;
        for (const ax of ["roll", "pitch", "yaw"]) s.att[ax] += s.rates[ax] * dt;
        const bx = Math.sin(s.att.pitch) * Math.cos(s.att.roll), bz = -Math.sin(s.att.roll);
        const dir = { x: Math.cos(s.att.yaw) * bx + Math.sin(s.att.yaw) * bz, y: Math.cos(s.att.pitch) * Math.cos(s.att.roll), z: -Math.sin(s.att.yaw) * bx + Math.cos(s.att.yaw) * bz };
        for (const ax of ["x", "y", "z"]) {
          const f = sum * dir[ax] + 0.42 * (p.baseWind[ax] - s.vel[ax]);
          s.vel[ax] += (f / p.mass - (ax === "y" ? 9.81 : 0)) * dt;
          s.pos[ax] += s.vel[ax] * dt;
