export default function makeController() {
  const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));
  let stepCount = 0;
  let kT = 20.0;
  let massEst = 0.78;
  let uf = 0.45;

  let tCal = null, vyCal = 0, yCal = 0;
  let intThrY = 0;

  let baseDx = 0, baseDz = 0;
  let gustDx = 0, gustDz = 0;
  let vxHat = 0, vyHat = 0, vzHat = 0;

  // Inner attitude & weak-motor disturbance observer
  let simIntRoll = 0, simIntPitch = 0;
  let uSimFiltRoll = 0, uSimFiltPitch = 0;
  let wHatRoll = 0, wHatPitch = 0;
  let alphaEqRoll = 0, alphaEqPitch = 0;
  let lastRollCmd = 0, lastPitchCmd = 0, lastThrustCmd = 0.45;

  let ix = 0, iy = 0, iz = 0;
  let currentGate = 0;
  let prevGate = null;
  let crossingGate = false;
  let descendMode = false;

  return {
    step(obs) {
      const dt = 0.01;
      const p = obs.pos, v = obs.vel, att = obs.att, rates = obs.rates;

      const alphaMotor = 1 - Math.exp(-dt / 0.04);
      uf += (lastThrustCmd - uf) * alphaMotor;

      // Update inner attitude disturbance observer
      if (stepCount === 0) {
        wHatRoll = rates.roll;
        wHatPitch = rates.pitch;
      } else {
        const errR = lastRollCmd - att.roll;
        const errP = lastPitchCmd - att.pitch;
        simIntRoll = clamp(simIntRoll + errR * dt, -0.35, 0.35);
        simIntPitch = clamp(simIntPitch + errP * dt, -0.35, 0.35);

        const uSimR = 65 * errR - 13 * rates.roll + 22 * simIntRoll;
        const uSimP = 65 * errP - 13 * rates.pitch + 22 * simIntPitch;
        uSimFiltRoll += (uSimR - uSimFiltRoll) * alphaMotor;
        uSimFiltPitch += (uSimP - uSimFiltPitch) * alphaMotor;

        if (p.y > 0.08) {
          const wPredR = wHatRoll + (uSimFiltRoll - 0.4 * wHatRoll - alphaEqRoll) * dt;
          const wPredP = wHatPitch + (uSimFiltPitch - 0.4 * wHatPitch - alphaEqPitch) * dt;
          const ewR = rates.roll - wPredR;
          const ewP = rates.pitch - wPredP;
          wHatRoll = wPredR + 0.55 * ewR;
          wHatPitch = wPredP + 0.55 * ewP;
          alphaEqRoll = clamp(alphaEqRoll - 14.0 * ewR, -14.0, 14.0);
          alphaEqPitch = clamp(alphaEqPitch - 14.0 * ewP, -14.0, 14.0);
        } else {
          wHatRoll = rates.roll;
          wHatPitch = rates.pitch;
        }
      }

      const bodyX = Math.sin(att.pitch) * Math.cos(att.roll);
      const bodyZ = -Math.sin(att.roll);
      const cy = Math.cos(att.yaw), sy = Math.sin(att.yaw);
      const dirX = cy * bodyX + sy * bodyZ;
      const dirY = Math.cos(att.pitch) * Math.cos(att.roll);
      const dirZ = -sy * bodyX + cy * bodyZ;

      if (stepCount === 0) {
        vxHat = v.x; vyHat = v.y; vzHat = v.z;
      }

      if (p.y > 0.085 && obs.t >= 0.08 && obs.t <= 1.95) {
        if (tCal === null) {
          tCal = obs.t;
          vyCal = v.y; yCal = p.y;
          intThrY = 0;
        } else {
          const dtCal = obs.t - tCal;
          intThrY += uf * dirY * dt;
          if (intThrY > 0.06 && dtCal > 0.08) {
            const dragCoeff = 0.42 / massEst;
            const totalAy = (v.y - vyCal) + 9.81 * dtCal + dragCoeff * (p.y - yCal);
            const newKT = clamp(totalAy / intThrY, 14.5, 27.5);
            kT = 0.75 * kT + 0.25 * newKT;
            massEst = clamp(15.1 / kT, 0.60, 0.95);
          }
        }
      }

      const dragCoeff = 0.42 / massEst;

      if (p.y > 0.08 && stepCount > 2) {
        const aThrustX = kT * uf * dirX;
        const aThrustZ = kT * uf * dirZ;
        const aKnownX = aThrustX - dragCoeff * vxHat;
        const aKnownZ = aThrustZ - dragCoeff * vzHat;

        const totalDx = baseDx + gustDx;
        const totalDz = baseDz + gustDz;
        const vPredX = vxHat + (aKnownX + totalDx) * dt;
        const vPredZ = vzHat + (aKnownZ + totalDz) * dt;
        const evX = v.x - vPredX;
        const evZ = v.z - vPredZ;

        if (obs.t < 1.98) {
          vxHat = vPredX + 0.55 * evX;
          vzHat = vPredZ + 0.55 * evZ;
          baseDx = clamp(baseDx + 14.0 * evX, -2.0, 2.0);
          baseDz = clamp(baseDz + 14.0 * evZ, -2.0, 2.0);
          gustDx = 0;
          gustDz = 0;
        } else {
          const jumpX = Math.abs(evX) > 0.025;
          const jumpZ = Math.abs(evZ) > 0.025;
          vxHat = vPredX + (jumpX ? 0.80 : 0.50) * evX;
          vzHat = vPredZ + (jumpZ ? 0.80 : 0.50) * evZ;
          gustDx = clamp(gustDx + (jumpX ? 38.0 : 16.0) * evX, -10.0, 10.0);
          gustDz = clamp(gustDz + (jumpZ ? 38.0 : 16.0) * evZ, -10.0, 10.0);
        }
      } else {
        vxHat = v.x; vyHat = v.y; vzHat = v.z;
      }

      const dxHat = baseDx + gustDx;
      const dzHat = baseDz + gustDz;

      const aNetX = kT * uf * dirX - dragCoeff * v.x + dxHat;
      const aNetZ = kT * uf * dirZ - dragCoeff * v.z + dzHat;

      let tx, ty, tz;
      let kpX = 5.0, kdX = 3.7;
      let kpZ = 5.6, kdZ = 4.1;
      let kpY = 6.2, kdY = 3.9;
      let maxVelX = 1.55, maxVelZ = 1.5, maxVelY = 1.5;

      if (obs.gateIndex < 3) {
        const gate = obs.nextGate.centre;
        if (currentGate !== obs.gateIndex) {
          const gates = [
            { x: -1.15, y: 1.05, z: -0.85 },
            { x: 0.15, y: 1.40, z: 0.25 },
            { x: 1.35, y: 1.05, z: 1.05 }
          ];
          prevGate = gates[currentGate];
          currentGate = obs.gateIndex;
          crossingGate = false;
          ix = 0; iz = 0;
        }
        const gx = gate.x, gy = gate.y, gz = gate.z;
        ty = gy;
        tz = gz;

        if (prevGate && p.x < prevGate.x + 0.15) {
          ty = prevGate.y;
          tz = prevGate.z;
          tx = prevGate.x + 0.38;
          kpZ = 7.2; kdZ = 4.5;
        } else {
          const distX = gx - p.x;
          const errZ = Math.abs(p.z - gz);
          const errY = Math.abs(p.y - gy);
          const tCross = clamp(distX / Math.max(0.20, v.x), 0.03, 0.35);
          const zPred = p.z + v.z * tCross + 0.25 * aNetZ * tCross * tCross;
          const yPred = p.y + v.y * tCross;

          if (!crossingGate) {
            if (distX > 0.03 && distX < 0.48 && errZ < 0.018 && Math.abs(zPred - gz) < 0.020 && Math.abs(v.z) < 0.09 && errY < 0.065 && Math.abs(v.y) < 0.22) {
              crossingGate = true;
            }
          } else {
            if (distX > 0.03 && (errZ > 0.024 || Math.abs(zPred - gz) > 0.026 || errY > 0.10 || Math.abs(yPred - gy) > 0.11)) {
              crossingGate = false;
            }
          }

          if (crossingGate) {
            tx = gx + 0.36;
            kpZ = 7.8; kdZ = 4.8;
            kpY = 7.0; kdY = 4.2;
            maxVelX = 1.15;
          } else {
            tx = gx - 0.26;
            kpZ = 6.2; kdZ = 4.3;
          }
        }
      } else {
        const pad = obs.pad.centre;
        tx = pad.x;
        tz = pad.z;
        if (currentGate !== 3) {
          prevGate = { x: 1.35, y: 1.05, z: 1.05 };
          currentGate = 3;
          ix = 0; iz = 0; iy = 0;
        }
        if (prevGate && p.x < prevGate.x + 0.15) {
          tz = prevGate.z;
          ty = prevGate.y;
          tx = pad.x;
        } else {
          const distXZ = Math.hypot(p.x - pad.x, p.z - pad.z);
          const speedXZ = Math.hypot(v.x, v.z);
          kpX = 6.0; kdX = 4.2;
          kpZ = 6.0; kdZ = 4.2;
          if (!descendMode) {
            ty = distXZ > 0.35 ? 0.35 : 0.14;
            if (distXZ < 0.12 && speedXZ < 0.30 && p.y < 0.24) {
              descendMode = true;
            }
          }
          if (descendMode) {
            ty = 0.025;
            kpX = 6.8; kdX = 4.5;
            kpZ = 6.8; kdZ = 4.5;
            if (distXZ > 0.138) {
              ty = 0.13;
              descendMode = false;
            }
          }
        }
      }

      if (Math.abs(tx - p.x) < 0.15 && Math.abs(v.x) < 0.20) {
        ix = clamp(ix + 1.8 * (tx - p.x) * dt, -0.22, 0.22);
      } else if (Math.abs(tx - p.x) > 0.22 || (tx - p.x) * ix < 0) {
        ix *= 0.85;
      }

      if (Math.abs(tz - p.z) < 0.14 && Math.abs(v.z) < 0.20) {
        iz = clamp(iz + 2.2 * (tz - p.z) * dt, -0.22, 0.22);
      } else if (Math.abs(tz - p.z) > 0.20 || (tz - p.z) * iz < 0) {
        iz *= 0.85;
      }

      if (Math.abs(ty - p.y) < 0.18 && Math.abs(v.y) < 0.25) {
        iy = clamp(iy + 1.6 * (ty - p.y) * dt, -0.35, 0.35);
      } else if (Math.abs(ty - p.y) > 0.25) {
        iy *= 0.90;
      }

      const desVx = clamp((kpX / kdX) * (tx - p.x) + ix, -maxVelX, maxVelX);
      const desVz = clamp((kpZ / kdZ) * (tz - p.z) + iz, -maxVelZ, maxVelZ);
      const desVy = clamp((kpY / kdY) * (ty - p.y) + iy, -maxVelY, maxVelY);

      const axCmd = kdX * (desVx - v.x) - 0.14 * aNetX;
      const azCmd = kdZ * (desVz - v.z) - 0.14 * aNetZ;
      const ayCmd = kdY * (desVy - v.y);

      const reqTx = clamp(axCmd - dxHat + dragCoeff * v.x, -5.8, 5.8);
      const reqTz = clamp(azCmd - dzHat + dragCoeff * v.z, -5.8, 5.8);
      const reqTy = clamp(ayCmd + 9.81 + dragCoeff * v.y, 2.8, 14.5);

      const tBodyX = cy * reqTx - sy * reqTz;
      const tBodyZ = sy * reqTx + cy * reqTz;

      const pitchDes = Math.atan2(tBodyX, reqTy);
      const rollDes = -Math.atan2(tBodyZ, Math.hypot(reqTy, tBodyX));

      const maxTilt = (obs.gateIndex === 3 && p.y < 0.13) ? 0.15 : 0.52;
      const rollComp = (alphaEqRoll - 22 * simIntRoll) / 65;
      const pitchComp = (alphaEqPitch - 22 * simIntPitch) / 65;
      const roll = clamp(rollDes + rollComp + 0.15 * (rollDes - att.roll) - 0.015 * rates.roll, -maxTilt, maxTilt);
      const pitch = clamp(pitchDes + pitchComp + 0.15 * (pitchDes - att.pitch) - 0.015 * rates.pitch, -maxTilt, maxTilt);

      let thrust = reqTy / (kT * Math.max(0.55, dirY));
      if (obs.gateIndex === 3 && descendMode && p.y <= 0.092 && Math.hypot(p.x - obs.pad.centre.x, p.z - obs.pad.centre.z) <= 0.135 && Math.hypot(v.x, v.y, v.z) < 0.42) {
        thrust = Math.min(thrust, (9.81 * 0.18) / kT);
      }
      thrust = clamp(thrust, 0.02, 0.78);

      const yawRate = clamp(-1.2 * att.yaw, -0.6, 0.6);

      lastRollCmd = roll;
      lastPitchCmd = pitch;
      lastThrustCmd = thrust;
      stepCount++;

      return { thrust, roll, pitch, yawRate };
    }
  };
}

