      let dPastX = 0, dPastZ = 0;
      let dFutureX = 0, dFutureZ = 0;
      let imminentZShock = false;

      if (knownParams !== null) {
        const wPast1 = windAt(knownParams, obs.t - 0.01);
        const wPast2 = windAt(knownParams, obs.t - 0.005);
        dPastX = dragCoeff * 0.5 * (wPast1.x + wPast2.x);
        dPastZ = dragCoeff * 0.5 * (wPast1.z + wPast2.z);

        // Weighted lookahead over [t, t + 0.06s] matching motor/attitude response
        const w0 = windAt(knownParams, obs.t);
        const w1 = windAt(knownParams, obs.t + 0.02);
        const w2 = windAt(knownParams, obs.t + 0.04);
        const w3 = windAt(knownParams, obs.t + 0.06);
        dFutureX = dragCoeff * (0.35 * w0.x + 0.30 * w1.x + 0.20 * w2.x + 0.15 * w3.x);
        dFutureZ = dragCoeff * (0.35 * w0.z + 0.30 * w1.z + 0.20 * w2.z + 0.15 * w3.z);

        for (const g of knownParams.gusts) {
          if (Math.abs(g.z) > 3.2) {
            const dtStart = g.start - obs.t;
            const dtEnd = g.end - obs.t;
            if ((dtStart > -0.08 && dtStart < 0.12) || (dtEnd > -0.08 && dtEnd < 0.10)) {
