        if (nearPrevGate) {
          tz = prevGate.z;
          ty = prevGate.y;
          tx = pad.x;
          kpX = 8.0; kdX = 4.8;
          kpZ = 8.0; kdZ = 4.8;
        } else {
          const distXZ = Math.hypot(p.x - pad.x, p.z - pad.z);
          const speedXZ = Math.hypot(v.x, v.z);
          const highTilt = Math.max(Math.abs(att.roll), Math.abs(att.pitch)) > 0.22;
          kpX = 6.4; kdX = 4.3;
          kpZ = 6.4; kdZ = 4.3;
          kpY = 8.0; kdY = 4.4;
          if (!descendMode) {
            ty = clamp(0.11 + 0.55 * distXZ, 0.11, 0.65);
            if (distXZ < 0.13 && speedXZ < 0.32 && p.y < 0.22 && !highTilt) {
              descendMode = true;
            }
          }
          if (descendMode) {
            ty = 0.04;
            kpX = 7.2; kdX = 4.6;
            kpZ = 7.2; kdZ = 4.6;
            kpY = 9.0; kdY = 4.5;
            if (distXZ > 0.14 || speedXZ > 0.40 || Math.max(Math.abs(att.roll), Math.abs(att.pitch)) > 0.25) {
              ty = 0.16;
              descendMode = false;
            }
