        thrust = Math.min(thrust, (9.81 * 0.65) / kT);
      }
      thrust = clamp(thrust, 0.05, 0.78);

      const yawRate = clamp(-1.2 * att.yaw, -0.6, 0.6);

      lastRollCmd = roll;
      lastPitchCmd = pitch;
      lastThrustCmd = thrust;
      stepCount++;

      return { thrust, roll, pitch, yawRate };
    }
  };
}

